// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed param: an address that will attempt to call setOwner
    function testFuzz_property(address caller, address newOwner) public {
        // keep addresses in normal EOA range (non-zero), but wide
        vm.assume(caller != address(0));
        vm.assume(newOwner != address(0));
        // determine admin and current owner
        address admin = address(this); // in setUp, c was deployed by this contract, so admin == this
        address initialOwner = c.owner();

        // We want to capture the universal property: only admin can call setOwner.
        // Under the reference implementation, any non-admin call to setOwner must revert.
        // Under the mutant, when owner != admin, a caller equal to owner can call setOwner.

        // Ensure the caller is not the admin to test the restriction
        vm.assume(caller != admin);

        // Drive the call as the fuzzed caller and record whether setOwner succeeds
        bool ok;
        vm.prank(caller);
        try c.setOwner(newOwner) returns (bool) {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference contract guarantees that if caller != admin, the call fails (ok == false).
        // The mutant allows success when caller == initialOwner (because it checks owner instead of admin),
        // so for some fuzzed inputs (caller == initialOwner and initialOwner != admin) ok will be true and the mutant breaks.
        assertTrue(!ok);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address deployer;

    function setUp() public { 
        // test runner (this contract) deploys C; msg.sender at deployment is address(this)
        // but in Foundry, the test contract is deployed by the test runner; to capture the "admin"
        // value used by C we record address(this) which will be the deployer
        deployer = address(this);
        c = new C();
    }

    // General rule to check: only the original deployer (admin) can successfully change owner.
    // Fuzz parameters:
    // - caller: the address attempting to call setOwner
    // - newOwner: the address passed to setOwner
    // The reference contract ensures that setOwner only succeeds when caller == admin.
    function testFuzz_property(address caller, address newOwner) public {
        // Keep domain wide: avoid trivial exclusion. Allow any addresses, including zero.
        // Arrange: ensure caller has some ETH so a call can be made if needed (not required here)
        vm.deal(caller, 1 ether);

        // Act: have `caller` attempt to call setOwner(newOwner)
        bool ok;
        // use vm.prank to set msg.sender for the call
        vm.prank(caller);
        try c.setOwner(newOwner) returns (bool success) {
            ok = success;
        } catch {
            ok = false;
        }

        // Assert exactly one general property that the correct contract always satisfies:
        // If the call succeeded (ok == true), then caller must be the original deployer (admin).
        // This reads c only via its public surface (we only used setOwner and will check ok flag).
        // The mutant that compares msg.sender to owner instead of admin will allow a caller equal
        // to the current owner (when owner != admin) to succeed even when caller != admin,
        // violating this property for some inputs. Thus this assertion distinguishes them.
        assertTrue(!ok || caller == deployer);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzzed params: attacker is a candidate caller, newOwner is the address to set
    function testFuzz_property(address attacker, address newOwner) public {
        // Keep domain wide: avoid zero-address for newOwner to make meaning clear but allow it otherwise
        // We do not overly constrain attacker so fuzzer can find cases where owner != admin
        vm.assume(newOwner != address(0));

        // admin is the deployer in setUp(); obtain it by creating a new contract to read admin cannot be read (private)
        // But we know admin == address(this) at deployment of C in setUp()? No: setUp deployed C from this test contract address.
        // In reference contract, admin was set to msg.sender (the test contract) when setUp created C. So admin == address(this).
        // To exercise the difference we need a scenario where owner != admin. After deployment, owner == admin too.
        // So first have the true admin (this test contract) change owner to some address via setOwner.

        // As the test contract is the deployer/admin, we can call setOwner to set owner to attacker (making owner != admin if attacker != address(this)).
        bool ok;
        try c.setOwner(attacker) {
            ok = true;
        } catch {
            ok = false;
        }
        // This call must succeed in the reference contract because caller is admin (the test contract that deployed C).
        // If it unexpectedly reverts, abort the test case (do not assert false) — keep admissible domain wide.
        if (!ok) return;

        // Now owner() == attacker (in the reference). The invariant we assert is:
        // For any subsequent caller X (we use attacker as the fuzzed caller), only admin (the original deployer) can change owner again.
        // So if a non-admin address (attacker) tries to call setOwner, it must fail in the reference contract.
        // The mutant that compares msg.sender == owner instead of admin will allow attacker (who is owner now) to succeed.

        // Simulate attacker trying to call setOwner to set owner to newOwner
        vm.prank(attacker);
        try c.setOwner(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // SINGLE assertion: in the correct contract, a call to setOwner by the current owner (who is not admin) must NOT succeed.
        // We assert that the call by attacker (who we earlier made the owner) did NOT succeed (ok == false) OR attacker == admin.
        // But admin == address(this); attacker is fuzzed — the universal property is: if caller != admin then setOwner must revert.
        // Equivalent single assertTrue reading c's public surface: after the attempted call, c.owner() must equal attacker when the call failed,
        // but must equal newOwner if the call succeeded. To make a single assertion that the reference always satisfies and the mutant breaks,
        // we assert that if attacker != address(this) then c.owner() != newOwner (i.e., non-admin caller cannot change owner).

        if (attacker != address(this)) {
            // After the attempted call, in the reference c.owner() should still be attacker (unchanged), so it must not equal newOwner.
            assertTrue(c.owner() != newOwner);
        } else {
            // If attacker is admin (address(this)), the call is allowed and owner should equal newOwner — in that case we do not assert anything restrictive.
            // To keep a single assertTrue in all executions, use a tautology for this branch: owner() == owner()
            assertTrue(c.owner() == c.owner());
        }
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the candidate new owner address
    function testFuzz_property(address newOwner) public {
        // keep domain wide; no assumptions needed
        // admin is deployer (this contract), so act as admin
        bool ok;
        // call setOwner as admin (this contract is admin by constructor of C)
        try c.setOwner(newOwner) returns (bool ret) {
            ok = ret;
        } catch {
            ok = false;
        }
        // General rule: on the reference implementation, setOwner always returns true for any input
        // (it returns the literal true). The mutant returns (owner != address(0)) and thus will return
        // false when newOwner == address(0). We assert the reference's behavior (return true) by
        // checking the call returned true for all fuzzed newOwner addresses.
        assertTrue(ok);
    }
}
